import { setTimeout as sleep } from 'node:timers/promises';
import type { DatabaseSync } from 'node:sqlite';
import { openDatabase, transaction } from './db.ts';
import { getJobRow, MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, type JobRow } from './jobs.ts';

const db: DatabaseSync = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 500;
let lastBeat = 0;

function heartbeat(force = false): void {
  const now = Date.now();
  if (!force && now - lastBeat < HEARTBEAT_MS) return;
  lastBeat = now;
  db.prepare(
    "INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at",
  ).run(now);
}

/**
 * Jobs still marked running belong to a previous worker that died mid-attempt. Only one worker
 * runs at a time, so they are put back in the queue and processed again.
 */
function recoverInterrupted(): void {
  db.prepare(
    "UPDATE jobs SET status = 'queued', completed = 0, available_at = ?, updated_at = ? WHERE status = 'running'",
  ).run(Date.now(), new Date().toISOString());
}

/** Atomically takes the oldest runnable queued job and starts an attempt on it. */
function claimNext(): JobRow | undefined {
  return transaction(db, () => {
    const next = db
      .prepare("SELECT id FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1")
      .get(Date.now()) as { id: string } | undefined;
    if (!next) return undefined;
    db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE id = ? AND status = 'queued'",
    ).run(new Date().toISOString(), next.id);
    return getJobRow(db, next.id);
  });
}

/** Records that an attempt was cut short by shutdown. The job goes back to the queue and the attempt is not retried in this process. */
function requeueForShutdown(id: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'queued', completed = 0, available_at = ?, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(Date.now(), new Date().toISOString(), id);
}

function failAttempt(id: string, attempt: number): void {
  const now = new Date().toISOString();
  if (attempt < MAX_ATTEMPTS) {
    db.prepare(
      "UPDATE jobs SET status = 'queued', completed = 0, available_at = ?, updated_at = ? WHERE id = ? AND status = 'running'",
    ).run(Date.now() + RETRY_DELAY_MS, now, id);
  } else {
    db.prepare(
      "UPDATE jobs SET status = 'failed', completed = 0, result_output = NULL, error = 'transient failure', updated_at = ? WHERE id = ? AND status = 'running'",
    ).run(now, id);
  }
}

function setProgress(id: string, completed: number): void {
  db.prepare("UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ? AND status = 'running'").run(
    completed,
    new Date().toISOString(),
    id,
  );
}

function complete(job: JobRow): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(job.input.toUpperCase(), new Date().toISOString(), job.id);
}

async function processJob(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  // Simulated transient failure: the attempt fails at its first step, before any progress.
  if (attempt <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (stopping) return requeueForShutdown(job.id);
    failAttempt(job.id, attempt);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return requeueForShutdown(job.id);
    setProgress(job.id, step);
  }
  complete(job);
}

async function main(): Promise<void> {
  heartbeat(true);
  recoverInterrupted();
  console.log('worker started');

  while (!stopping) {
    try {
      heartbeat();
      const job = claimNext();
      if (job) {
        await processJob(job);
      } else {
        await sleep(IDLE_POLL_MS);
      }
    } catch (e) {
      console.error('worker error:', e);
      await sleep(IDLE_POLL_MS);
    }
  }

  db.prepare("DELETE FROM heartbeats WHERE name = 'worker'").run();
  db.close();
  console.log('worker stopped');
}

main().catch((e: unknown) => {
  console.error('worker failed:', e);
  process.exit(1);
});

